def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates=[]
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0:
            candidates.append((sum(row.count(grid[0][c]) for row in grid), 'v', c))
    for r,row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            candidates.append((sum(rr.count(row[0]) for rr in grid), 'h', r))
    if not candidates: raise ValueError('separator missing')
    _, axis, pos = min(candidates)
    if axis == 'v':
        n=min(pos,w-pos-1)
        return [[2 if grid[r][j] and grid[r][pos+1+j] else 0 for j in range(n)] for r in range(h)]
    n=min(pos,h-pos-1)
    return [[2 if grid[i][c] and grid[pos+1+i][c] else 0 for c in range(w)] for i in range(n)]
